import (
	"database/sql"
	"fmt"
)

func testPasswordStorage(db *sql.DB) {
	username := "testuser"
	password := "testpassword"
	query := "INSERT INTO users (username, password, userInfo) VALUES (?, ?, ?)"
	_, err := db.Exec(query, username, password, "Test User Info")
	if err != nil {
		fmt.Println("Error inserting user:", err)
		return
	}
	fmt.Println("User added successfully with plain text password.")
}
